pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= 100 ether);
        vm.deal(address(this), amount);
        (bool ok,) = address(c).call{value: amount}("");
        if (ok) {
            assertEq(amount, 10 ether, "Non-reverting call must send exactly 10 ether");
        }
    }
}
